+#include "src/vm_config_parser.h"
+#include <stdio.h>
+#include <string.h>
+
+int main() {
+    struct vm_hardware_config cfg;
+    int r;
+
+    // Test 1: valid input
+    r = parse_vm_config("cpu_model=Intel,memory_mb=8192,disk_path=/var/vm/disk.img,network_adapter=virtio", &cfg);
+    printf("Test 1: r=%d, cpu_model='%s', memory_mb=%d, disk_path='%s', network_adapter='%s'\n",
+           r, cfg.cpu_model, cfg.memory_mb, cfg.disk_path, cfg.network_adapter);
+
+    // Test 2: empty string
+    r = parse_vm_config("", &cfg);
+    printf("Test 2 (empty): r=%d (expect -1)\n", r);
+
+    // Test 3: NULL
+    r = parse_vm_config(NULL, &cfg);
+    printf("Test 3 (NULL): r=%d (expect -1)\n", r);
+
+    // Test 4: cpu_model too long
+    char long_cpu[300];
+    memset(long_cpu, 'A', 200);
+    long_cpu[200] = '\0';
+    char buf[500];
+    snprintf(buf, sizeof(buf), "cpu_model=%s,memory_mb=8192,disk_path=/var/vm/disk.img,network_adapter=virtio", long_cpu);
+    r = parse_vm_config(buf, &cfg);
+    printf("Test 4 (long cpu): r=%d (expect -1)\n", r);
+
+    // Test 5: disk_path too long
+    memset(long_cpu, 'B', 300);
+    long_cpu[300] = '\0';
+    snprintf(buf, sizeof(buf), "cpu_model=Intel,memory_mb=8192,disk_path=%s,network_adapter=virtio", long_cpu);
+    r = parse_vm_config(buf, &cfg);
+    printf("Test 5 (long disk): r=%d (expect -1)\n", r);
+
+    // Test 6: network_adapter too long
+    memset(long_cpu, 'C', 100);
+    long_cpu[100] = '\0';
+    snprintf(buf, sizeof(buf), "cpu_model=Intel,memory_mb=8192,disk_path=/var/vm/disk.img,network_adapter=%s", long_cpu);
+    r = parse_vm_config(buf, &cfg);
+    printf("Test 6 (long net): r=%d (expect -1)\n", r);
+
+    // Test 7: cpu_model exactly 127 chars (should succeed)
+    memset(long_cpu, 'D', 127);
+    long_cpu[127] = '\0';
+    snprintf(buf, sizeof(buf), "cpu_model=%s,memory_mb=8192,disk_path=/var/vm/disk.img,network_adapter=virtio", long_cpu);
+    r = parse_vm_config(buf, &cfg);
+    printf("Test 7 (cpu=127): r=%d (expect 0)\n", r);
+
+    // Test 8: missing field
+    r = parse_vm_config("cpu_model=Intel,memory_mb=8192,disk_path=/var/vm/disk.img", &cfg);
+    printf("Test 8 (missing net): r=%d (expect -1)\n", r);
+
+    // Test 9: extra field
+    r = parse_vm_config("cpu_model=Intel,memory_mb=8192,disk_path=/var/vm/disk.img,network_adapter=virtio,extra=foo", &cfg);
+    printf("Test 9 (extra field): r=%d (expect -1)\n", r);
+
+    return 0;
+}

