+ * the string or preceded by a comma).
+ *
+ * @param str The configuration line to search.
+ * @param key The key including the trailing '=' character.
+ * @return Pointer to the start of the value, or NULL if the key is not found.
+ */
+static const char *find_value(const char *str, const char *key)
+{
+    const char *p = str;
+    size_t key_len = strlen(key);
+
+    while ((p = strstr(p, key)) != NULL) {
+        if (p == str || *(p - 1) == ',') {
+            return p + key_len;
+        }
+        p += key_len;
+    }
+    return NULL;
+}
+
+int parse_vm_config(const char* config_line, struct vm_hardware_config* hw_config)
+{
+    const char *cpu_val;
+    const char *mem_val;
+    const char *disk_val;
+    const char *net_val;
+    char mem_str[32];
+    size_t len;
+
+    /* Validate inputs */
+    if (!config_line || !hw_config || config_line[0] == '\0') {
+        return -1;
+    }
+
+    /* Clear output structure */
+    memset(hw_config, 0, sizeof(*hw_config));
+
+    /* --- cpu_model --- */
+    cpu_val = find_value(config_line, "cpu_model=");
+    if (!cpu_val) {
+        return -1;
+    }
+    len = strcspn(cpu_val, ",");
+    if (len == 0 || len >= sizeof(hw_config->cpu_model)) {
+        return -1;
+    }
+    if (sscanf(cpu_val, "%127[^,]", hw_config->cpu_model) != 1) {
+        return -1;
+    }
+
+    /* --- memory_mb --- */
+    mem_val = find_value(config_line, "memory_mb=");
+    if (!mem_val) {
+        return -1;
+    }
+    len = strcspn(mem_val, ",");
+    if (len == 0 || len >= sizeof(mem_str)) {
+        return -1;
+    }
+    if (sscanf(mem_val, "%31[^,]", mem_str) != 1) {
+        return -1;
+    }
+    {
+        char *endptr;
+        long mem_long = strtol(mem_str, &endptr, 10);
+        if (*endptr != '\0' || mem_long < 0 || mem_long > INT_MAX) {
+            return -1;
+        }
+        hw_config->memory_mb = (int)mem_long;
+    }
+
+    /* --- disk_path --- */
+    disk_val = find_value(config_line, "disk_path=");
+    if (!disk_val) {
+        return -1;
+    }
+    len = strcspn(disk_val, ",");
+    if (len == 0 || len >= sizeof(hw_config->disk_path)) {
+        return -1;
+    }
+    if (sscanf(disk_val, "%255[^,]", hw_config->disk_path) != 1) {
+        return -1;
+    }
+
+    /* --- network_adapter --- */
+    net_val = find_value(config_line, "network_adapter=");
+    if (!net_val) {
+        return -1;
+    }
+    len = strcspn(net_val, ",");
+    if (len == 0 || len >= sizeof(hw_config->network_adapter)) {
+        return -1;
+    }
+    if (sscanf(net_val, "%63[^,]", hw_config->network_adapter) != 1) {
+        return -1;
+    }
+
+    return 0;
+}

